        "description": "Percent of English learners in the district. Controls for language composition that can affect test scores.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english"
        ]
      },
      {
        "description": "Percent of students qualifying for reduced-price lunch. Controls for poverty within district.",
        "is_moderator": false,
